\usepackage{amsmath}
\usetikzlibrary{calc}
\begin{document}
\begin{tikzpicture}[line width=0.8pt, line join=round]
\coordinate (A) at (0.865,3.370);
\coordinate (B) at (-2.819,-1.437);
\coordinate (C) at (2.692,-2.404);
\coordinate (D) at (-0.321,-3.352);
\coordinate (I) at (0.270,0.009);









\draw (I) circle[radius=3.420];


\draw (A) -- (B);
\draw (A) -- (C);
\draw (B) -- (C);
\draw (B) -- (D);
\draw (C) -- (D);
\draw (A) -- (I);
\draw (I) -- (D);


\draw[dash pattern=on 4pt off 3pt] (B) -- (I);


\fill (I) circle[radius=3.500pt];

\node[above] at (A) {\fontsize{17.5}{21}\selectfont $A$};
\node[left] at (B) {\fontsize{17.5}{21}\selectfont $B$};
\node[right] at (C) {\fontsize{17.5}{21}\selectfont $C$};
\node[below] at (D) {\fontsize{17.5}{21}\selectfont $D$};
\node[right] at (I) {\fontsize{17.5}{21}\selectfont $I$};
\end{tikzpicture}
\end{document}

